export const masterMarketSeedData: MasterMarketSeed[] = (
  [] as MasterMarketSeed[]
).concat(
  masterMarketSeedDataPart01,
  masterMarketSeedDataPart02,
  masterMarketSeedDataPart03,
  masterMarketSeedDataPart04,
  masterMarketSeedDataPart05,
  masterMarketSeedDataPart06,
  masterMarketSeedDataPart07,
  masterMarketSeedDataPart08,
  masterMarketSeedDataPart09,
  masterMarketSeedDataPart10,
  masterMarketSeedDataPart11,
  masterMarketSeedDataPart12,
  masterMarketSeedDataPart13,
  masterMarketSeedDataPart14,
  masterMarketSeedDataPart15,
  masterMarketSeedDataPart16,
);

const chunkArray = <T>(items: T[], size: number): T[][] => {
  const chunks: T[][] = [];

  for (let index = 0; index < items.length; index += size) {
    chunks.push(items.slice(index, index + size));
  }

  return chunks;
};

export async function seedMasterMarkets(prisma: PrismaClient): Promise<void> {
  const syncedAt = new Date();
  // const batches = chunkArray(masterMarketSeedData, 100);
  const batches = chunkArray(masterMarketSeedData, 25);

  for (const batch of batches) {
    const operations = batch.map((item) =>
      prisma.masterMarket.upsert({
        where: {
          marketCode_boothCode: {
            marketCode: item.marketCode,
            boothCode: item.boothCode,
          },
        },
        create: { ...item, syncedAt },
        update: {
          sourceMarketId: item.sourceMarketId,
          sourceBoothId: item.sourceBoothId,
          marketName: item.marketName,
          boothName: item.boothName,
          marketStatus: item.marketStatus,
          boothStatus: item.boothStatus,
          sourceMarketCreatedAt: item.sourceMarketCreatedAt,
          sourceMarketUpdatedAt: item.sourceMarketUpdatedAt,
          sourceBoothCreatedAt: item.sourceBoothCreatedAt,
          sourceBoothUpdatedAt: item.sourceBoothUpdatedAt,
          syncedAt,
        },
      }),
    );

    await prisma.$transaction(operations);
  }

  console.info(
    `[seed] master_market completed: ${masterMarketSeedData.length} records`,
  );
}
